      <span class="hljs-bullet">-</span> <span class="hljs-string">GOAT_DB_PORT=3306</span>
      <span class="hljs-bullet">-</span> <span class="hljs-string">GOAT_DB_USER=webgoat</span>
      <span class="hljs-bullet">-</span> <span class="hljs-string">GOAT_DB_PASS=webgoat</span>

  <span class="hljs-attr">db:</span>
    <span class="hljs-attr">build:</span> <span class="hljs-string">./mysql</span>
    <span class="hljs-attr">ports:</span>
      <span class="hljs-bullet">-</span> <span class="hljs-string">"3306:3306"</span>
    <span class="hljs-attr">environment:</span>
      <span class="hljs-bullet">-</span> <span class="hljs-string">MYSQL_ROOT_PASSWORD=webgoat</span>
      <span class="hljs-bullet">-</span> <span class="hljs-string">MYSQL_DATABASE=webgoat_db</span>
