</span>): <span class="hljs-title">void</span> </span>{
    <span class="hljs-comment">// The PublicKeyCredentialCreationOptions should be configured according to the Relying Party's needs</span>
    <span class="hljs-variable">$publicKeyCredential</span> = <span class="hljs-variable">$server</span>-&gt;<span class="hljs-title function_ invoke__">createAndCheckAttestation</span>(<span class="hljs-variable">$_POST</span>, <span class="hljs-variable">$creationOptions</span>);

    <span class="hljs-variable">$attestationObject</span> = <span class="hljs-variable">$publicKeyCredential</span>-&gt;<span class="hljs-title function_ invoke__">getResponse</span>()-&gt;<span class="hljs-title function_ invoke__">getAttestationObject</span>();
    <span class="hljs-variable">$trustPath</span> = <span class="hljs-variable">$attestationObject</span>-&gt;<span class="hljs-title function_ invoke__">getAttStmt</span>()-&gt;<span class="hljs-title function_ invoke__">getTrustPath</span>();

    <span class="hljs-keyword">if</span> (<span class="hljs-variable">$trustPath</span> <span class="hljs-keyword">instanceof</span> CertificateTrustPath) {
