  <span class="hljs-keyword">const</span> publicKeyCredentialCreationOptions = {
    rp,
    user,
    <span class="hljs-attr">challenge</span>: <span class="hljs-title class_">Uint8Array</span>.<span class="hljs-title function_">from</span>(<span class="hljs-title function_">atob</span>(challenge), <span class="hljs-function"><span class="hljs-params">c</span> =&gt;</span> c.<span class="hljs-title function_">charCodeAt</span>(<span class="hljs-number">0</span>)),
