  };

  <span class="hljs-keyword">try</span> {
    <span class="hljs-keyword">const</span> credential = <span class="hljs-keyword">await</span> navigator.<span class="hljs-property">credentials</span>.<span class="hljs-title function_">create</span>({ <span class="hljs-attr">publicKey</span>: publicKeyCredentialCreationOptions });

    <span class="hljs-comment">// Send the credential.response (AuthenticatorAttestationResponse) to the server</span>
