  <span class="hljs-keyword">const</span> attestationResponse = {
    <span class="hljs-attr">id</span>: response.<span class="hljs-property">id</span>,
    <span class="hljs-attr">rawId</span>: <span class="hljs-title function_">btoa</span>(<span class="hljs-title class_">String</span>.<span class="hljs-property">fromCharCode</span>.<span class="hljs-title function_">apply</span>(<span class="hljs-literal">null</span>, <span class="hljs-keyword">new</span> <span class="hljs-title class_">Uint8Array</span>(response.<span class="hljs-property">rawId</span>))),
