  }
};

<span class="hljs-comment">// Use async/await to connect to the database</span>
<span class="hljs-keyword">async</span> <span class="hljs-keyword">function</span> <span class="hljs-title function_">connectToDatabase</span>(<span class="hljs-params"></span>) {
