    <span class="hljs-variable language_">console</span>.<span class="hljs-title function_">log</span>(result.<span class="hljs-property">recordset</span>); <span class="hljs-comment">// Output the results to the console</span>

  } <span class="hljs-keyword">catch</span> (err) {
    <span class="hljs-variable language_">console</span>.<span class="hljs-title function_">error</span>(<span class="hljs-string">'Error connecting to SQL Server:'</span>, err.<span class="hljs-property">message</span>);
