<span class="hljs-type">int</span> <span class="hljs-title function_">connect_to_server</span><span class="hljs-params">(SOCKET sock, <span class="hljs-type">const</span> <span class="hljs-type">char</span> *server_ip, <span class="hljs-type">const</span> <span class="hljs-type">char</span> *server_port)</span> {
    <span class="hljs-class"><span class="hljs-keyword">struct</span> <span class="hljs-title">addrinfo</span> *<span class="hljs-title">result</span> =</span> <span class="hljs-literal">NULL</span>, *ptr = <span class="hljs-literal">NULL</span>, hints;
