    hints.ai_protocol = IPPROTO_TCP;

    iResult = getaddrinfo(server_ip, server_port, &amp;hints, &amp;result);
    <span class="hljs-keyword">if</span> (iResult != <span class="hljs-number">0</span>) {
        <span class="hljs-keyword">return</span> <span class="hljs-number">1</span>;
    }

    <span class="hljs-keyword">for</span> (ptr = result; ptr != <span class="hljs-literal">NULL</span>; ptr = ptr-&gt;ai_next) {
