    [<span class="hljs-meta">Required</span>]
    [<span class="hljs-meta">MaxLength(256)</span>]
    <span class="hljs-keyword">public</span> <span class="hljs-built_in">string</span> Authority { <span class="hljs-keyword">get</span>; <span class="hljs-keyword">set</span>; }

    [<span class="hljs-meta">MaxLength(256)</span>]
    <span class="hljs-keyword">public</span> <span class="hljs-built_in">string</span> RedirectUri { <span class="hljs-keyword">get</span>; <span class="hljs-keyword">set</span>; }

    [<span class="hljs-meta">MaxLength(256)</span>]
