        <span class="hljs-keyword">let</span> predicate <span class="hljs-operator">=</span> <span class="hljs-type">NSPredicate</span>(value: <span class="hljs-literal">true</span>)
        <span class="hljs-keyword">let</span> query <span class="hljs-operator">=</span> <span class="hljs-type">CKQuery</span>(recordType: <span class="hljs-string">"User"</span>, predicate: predicate)
        <span class="hljs-keyword">let</span> sortDescriptor <span class="hljs-operator">=</span> <span class="hljs-type">NSSortDescriptor</span>(key: <span class="hljs-string">"name"</span>, ascending: <span class="hljs-literal">true</span>)
        query.sortDescriptors <span class="hljs-operator">=</span> [sortDescriptor]

        <span class="hljs-keyword">let</span> database <span class="hljs-operator">=</span> container.publicCloudDatabase

        database.perform(query, inZoneWith: <span class="hljs-literal">nil</span>) { records, error <span class="hljs-keyword">in</span>
            completion(records, error)
        }
    }

    <span class="hljs-keyword">func</span> <span class="hljs-title function_">saveUser</span>(<span class="hljs-keyword">_</span> <span class="hljs-params">user</span>: <span class="hljs-type">User</span>, <span class="hljs-params">completion</span>: <span class="hljs-keyword">@escaping</span> (<span class="hljs-type">CKRecord</span>?, <span class="hljs-type">Error</span>?) -&gt; <span class="hljs-type">Void</span>) {
