    <span class="hljs-keyword">private</span> <span class="hljs-keyword">let</span> networkManager <span class="hljs-operator">=</span> <span class="hljs-type">UserNetworkManager</span>()

    <span class="hljs-keyword">func</span> <span class="hljs-title function_">fetchUsers</span>() {
        isLoading <span class="hljs-operator">=</span> <span class="hljs-literal">true</span>

        networkManager.fetchUsers()

        <span class="hljs-variable">$networkManager</span>.users
            .receive(on: <span class="hljs-type">DispatchQueue</span>.main)
            .assign(to: <span class="hljs-operator">&amp;</span><span class="hljs-variable">$users</span>)
    }
}
</code></div></div></pre><p>And here's an example of how you could use the <code>UserListViewModel</code> in a view:</p><pre><div class="bg-black rounded-md mb-4"><div class="flex items-center relative text-gray-200 bg-gray-800 px-4 py-2 text-xs font-sans"><span>swift</span><svg stroke="currentColor" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" height="1em" width="1em" xmlns="http://www.w3.org/2000/svg"></svg>Copy code</div><div><code class="!whitespace-pre hljs language-swift"><span class="hljs-keyword">struct</span> <span class="hljs-title class_">UserListView</span>: <span class="hljs-title class_">View</span> {
    <span class="hljs-meta">@StateObject</span> <span class="hljs-keyword">private</span> <span class="hljs-keyword">var</span> viewModel <span class="hljs-operator">=</span> <span class="hljs-type">UserListViewModel</span>()

    <span class="hljs-keyword">var</span> body: <span class="hljs-keyword">some</span> <span class="hljs-type">View</span> {
