                .foregroundColor(.blue)
                .opacity(viewModel.isLoading <span class="hljs-operator">?</span> <span class="hljs-number">1</span> : <span class="hljs-number">0</span>)
        )
    }
}
</code></div></div></pre><p>Note that this example only shows how to fetch and display data, but you would also need to implement saving and updating data using Core Data and CloudKit if you wanted to use those technologies for persistence.</p></div>'},  {'from': 'human', 'value': 'can you continue with an example for saving and updating date with CloudKit and API calls?'},  {'from': 'gpt', 'value': '<div><p>Sure! Here's an example of how you could use CloudKit and API calls to save and update data in a SwiftUI MVVM application.</p><p>First, let's update the <code>User</code> model to include a <code>recordID</code> property, which will be used to store the CloudKit record ID for each user:</p><pre><div class="bg-black rounded-md mb-4"><div class="flex items-center relative text-gray-200 bg-gray-800 px-4 py-2 text-xs font-sans"><span>swift</span><svg stroke="currentColor" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" height="1em" width="1em" xmlns="http://www.w3.org/2000/svg"></svg>Copy code</div><div><code class="!whitespace-pre hljs language-swift"><span class="hljs-keyword">struct</span> <span class="hljs-title class_">User</span>: <span class="hljs-title class_">Codable</span>, <span class="hljs-title class_">Identifiable</span> {
