            <span class="hljs-keyword">guard</span> <span class="hljs-keyword">let</span> response <span class="hljs-operator">=</span> response <span class="hljs-keyword">as?</span> <span class="hljs-type">HTTPURLResponse</span> <span class="hljs-keyword">else</span> {
