<span class="hljs-keyword">class</span> <span class="hljs-title class_">Persistence</span> {
    <span class="hljs-keyword">static</span> <span class="hljs-keyword">var</span> shared <span class="hljs-operator">=</span> <span class="hljs-type">Persistence</span>()

    <span class="hljs-keyword">let</span> container: <span class="hljs-type">NSPersistentContainer</span>

    <span class="hljs-keyword">private</span> <span class="hljs-keyword">init</span>() {
        container <span class="hljs-operator">=</span> <span class="hljs-type">NSPersistentContainer</span>(name: <span class="hljs-string">"Posts"</span>)
        container.loadPersistentStores { (storeDescription, error) <span class="hljs-keyword">in</span>
            <span class="hljs-keyword">if</span> <span class="hljs-keyword">let</span> error <span class="hljs-operator">=</span> error {
                <span class="hljs-built_in">fatalError</span>(<span class="hljs-string">"Failed to load persistent stores: <span class="hljs-subst">\(error)</span>"</span>)
            }
        }
    }

    <span class="hljs-keyword">func</span> <span class="hljs-title function_">save</span>() {
        <span class="hljs-keyword">let</span> context <span class="hljs-operator">=</span> container.viewContext

        <span class="hljs-keyword">if</span> context.hasChanges {
            <span class="hljs-keyword">do</span> {
                <span class="hljs-keyword">try</span> context.save()
