	<span class="hljs-comment">// Feature 2: Total length of the URL</span>
	totalUrlLength := <span class="hljs-type">float64</span>(urlLength)

	<span class="hljs-comment">// Feature 3: Number of key-value pairs in the query string</span>
	parsedUrl, err := url.Parse(request.URL)
	<span class="hljs-keyword">if</span> err != <span class="hljs-literal">nil</span> {
		fmt.Printf(<span class="hljs-string">"Error parsing URL: %v\n"</span>, err)
		<span class="hljs-keyword">return</span> <span class="hljs-literal">false</span>
	}
	queryParams := parsedUrl.Query()
	numKeyValuePairs := <span class="hljs-type">float64</span>(<span class="hljs-built_in">len</span>(queryParams))

	<span class="hljs-comment">// Combine features into a single slice</span>
	features := []<span class="hljs-type">float64</span>{encodedCharsPercentage, totalUrlLength, numKeyValuePairs}

	<span class="hljs-comment">// Historical data (each row represents a request; each column represents a feature)</span>
	historicalData := [][]<span class="hljs-type">float64</span>{
		{<span class="hljs-number">0.02</span>, <span class="hljs-number">60</span>, <span class="hljs-number">2</span>},
