<span class="hljs-function"><span class="hljs-keyword">func</span> <span class="hljs-title">splitDataset</span><span class="hljs-params">(features *mat64.Dense, labels []<span class="hljs-type">bool</span>, trainFraction <span class="hljs-type">float64</span>)</span></span> (*mat64.Dense, []<span class="hljs-type">bool</span>, *mat64.Dense, []<span class="hljs-type">bool</span>) {
	numDataPoints, numFeatures := features.Dims()
