	perm := rand.Perm(numDataPoints)
	trainFeatures := mat64.NewDense(trainSize, numFeatures, <span class="hljs-literal">nil</span>)
	trainLabels := <span class="hljs-built_in">make</span>([]<span class="hljs-type">bool</span>, trainSize)
	testFeatures := mat64.NewDense(numDataPoints-trainSize, numFeatures, <span class="hljs-literal">nil</span>)
	testLabels := <span class="hljs-built_in">make</span>([]<span class="hljs-type">bool</span>, numDataPoints-trainSize)

	<span class="hljs-keyword">for</span> i, v := <span class="hljs-keyword">range</span> perm[:trainSize] {
		trainFeatures.SetRow(i, features.RawRowView(v))
		trainLabels[i] = labels[v]
