	<span class="hljs-keyword">for</span> i, v := <span class="hljs-keyword">range</span> perm[trainSize:] {
		testFeatures.SetRow(i-trainSize, features.RawRowView(v))
		testLabels[i-trainSize] = labels[v]
	}

	<span class="hljs-keyword">return</span> trainFeatures, trainLabels, testFeatures, testLabels
}

<span class="hljs-function"><span class="hljs-keyword">func</span> <span class="hljs-title">trainLogisticRegression</span><span class="hljs-params">(trainFeatures *mat64.Dense, trainLabels []<span class="hljs-type">bool</span>)</span></span> *stat.LogisticRegression {
