}

<span class="hljs-function"><span class="hljs-keyword">func</span> <span class="hljs-title">evaluateLogisticRegression</span><span class="hljs-params">(model *stat.LogisticRegression, testFeatures *mat64.Dense, testLabels []<span class="hljs-type">bool</span>)</span></span> <span class="hljs-type">float64</span> {
	numDataPoints, numFeatures := testFeatures.Dims()
