<span class="hljs-keyword">def</span> <span class="hljs-title function_">convert_attackiq_to_mitre</span>(<span class="hljs-params">attack_graph</span>):
    <span class="hljs-string">"""
    Converts an AttackIQ formatted attack graph to a MITRE ATT&amp;CK formatted attack flow.
    """</span>

    mitre_attack_flow = {
        <span class="hljs-string">"name"</span>: attack_graph[<span class="hljs-string">"name"</span>],
        <span class="hljs-string">"description"</span>: attack_graph[<span class="hljs-string">"description"</span>],
        <span class="hljs-string">"tactic"</span>: <span class="hljs-string">""</span>,
        <span class="hljs-string">"technique"</span>: [],
        <span class="hljs-string">"sub-technique"</span>: [],
        <span class="hljs-string">"data-source"</span>: [],
        <span class="hljs-string">"targeted-platforms"</span>: []
    }

    <span class="hljs-keyword">for</span> node <span class="hljs-keyword">in</span> attack_graph[<span class="hljs-string">"nodes"</span>]:
        <span class="hljs-keyword">if</span> node[<span class="hljs-string">"node_type"</span>] == <span class="hljs-string">"tactic"</span>:
            mitre_attack_flow[<span class="hljs-string">"tactic"</span>] = node[<span class="hljs-string">"name"</span>]
        <span class="hljs-keyword">elif</span> node[<span class="hljs-string">"node_type"</span>] == <span class="hljs-string">"technique"</span>:
            mitre_attack_flow[<span class="hljs-string">"technique"</span>].append({
                <span class="hljs-string">"name"</span>: node[<span class="hljs-string">"name"</span>],
                <span class="hljs-string">"id"</span>: node[<span class="hljs-string">"external_id"</span>],
                <span class="hljs-string">"description"</span>: node[<span class="hljs-string">"description"</span>],
                <span class="hljs-string">"sub-technique"</span>: []
            })
        <span class="hljs-keyword">elif</span> node[<span class="hljs-string">"node_type"</span>] == <span class="hljs-string">"subtechnique"</span>:
            technique = <span class="hljs-built_in">next</span>(<span class="hljs-built_in">filter</span>(<span class="hljs-keyword">lambda</span> x: x[<span class="hljs-string">"id"</span>] == node[<span class="hljs-string">"parent_node_external_id"</span>], mitre_attack_flow[<span class="hljs-string">"technique"</span>]))
            technique[<span class="hljs-string">"sub-technique"</span>].append({
                <span class="hljs-string">"name"</span>: node[<span class="hljs-string">"name"</span>],
                <span class="hljs-string">"id"</span>: node[<span class="hljs-string">"external_id"</span>],
                <span class="hljs-string">"description"</span>: node[<span class="hljs-string">"description"</span>]
            })
        <span class="hljs-keyword">elif</span> node[<span class="hljs-string">"node_type"</span>] == <span class="hljs-string">"data_source"</span>:
            mitre_attack_flow[<span class="hljs-string">"data-source"</span>].append(node[<span class="hljs-string">"name"</span>])
        <span class="hljs-keyword">elif</span> node[<span class="hljs-string">"node_type"</span>] == <span class="hljs-string">"target_platform"</span>:
            mitre_attack_flow[<span class="hljs-string">"targeted-platforms"</span>].append(node[<span class="hljs-string">"name"</span>])

    <span class="hljs-keyword">return</span> json.dumps(mitre_attack_flow, indent=<span class="hljs-number">4</span>)
