<span class="hljs-keyword">public</span> X509Certificate <span class="hljs-title function_">loadCertificate</span><span class="hljs-params">(String alias)</span> <span class="hljs-keyword">throws</span> Exception {
    <span class="hljs-type">String</span> <span class="hljs-variable">query</span> <span class="hljs-operator">=</span> <span class="hljs-string">"SELECT certificate FROM certificates WHERE alias = ?"</span>;
