tColor" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" height="1em" width="1em" xmlns="http://www.w3.org/2000/svg"></svg>Copy code</div><div><code class="!whitespace-pre hljs language-php-template"><span class="xml">List<span class="hljs-tag">&lt;<span class="hljs-name">Type</span>&gt;</span> listName = new ArrayList<span class="hljs-tag">&lt;&gt;</span>();
