        inventory<span class="hljs-selector-attr">[_productId]</span><span class="hljs-selector-class">.quantity</span> -= _quantity;
        emit <span class="hljs-built_in">ProductRemoved</span>(_productId, inventory[_productId].name, _quantity);
    }

    function <span class="hljs-built_in">updateProduct</span>(uint256 _productId, string memory _name, uint256 _quantity) public {
        <span class="hljs-built_in">require</span>(inventory[_productId].quantity &gt; <span class="hljs-number">0</span>, "Product not found");
        inventory<span class="hljs-selector-attr">[_productId]</span><span class="hljs-selector-class">.name</span> = _name;
        inventory<span class="hljs-selector-attr">[_productId]</span><span class="hljs-selector-class">.quantity</span> = _quantity;
        emit <span class="hljs-built_in">ProductUpdated</span>(_productId, _name, _quantity);
    }

    function <span class="hljs-built_in">getProduct</span>(uint256 _productId) public view returns (string memory, uint256) {
        return (inventory[_productId].name, inventory[_productId].quantity);
    }

    function <span class="hljs-built_in">verifyAuthenticity</span>(uint256 _productId, string memory _name) public view returns (bool) {
        if (bytes(inventory[_productId].name)<span class="hljs-selector-class">.length</span> == <span class="hljs-built_in">bytes</span>(_name)<span class="hljs-selector-class">.length</span>) {
            return (keccak256(bytes(inventory[_productId].name)) == <span class="hljs-built_in">keccak256</span>(bytes(_name)));
        }
        return false;
    }

    function <span class="hljs-built_in">verifyQuantity</span>(uint256 _productId, uint256 _quantity) public view returns (bool) {
        return (inventory[_productId].quantity &gt;= _quantity);
    }

    function <span class="hljs-built_in">audit</span>() public view returns (string memory) {
        string memory auditString;
        for (uint256 i = <span class="hljs-number">1</span>; i &lt; nextProductId; i++) {
            string memory name = inventory<span class="hljs-selector-attr">[i]</span><span class="hljs-selector-class">.name</span>;
            uint256 quantity = inventory<span class="hljs-selector-attr">[i]</span><span class="hljs-selector-class">.quantity</span>;
            auditString = <span class="hljs-built_in">string</span>(abi.encodePacked(auditString, "Product ID: ", uint2str(i), " | Name: <span class="hljs-string">", name, "</span> | Quantity: <span class="hljs-string">", uint2str(quantity), "</span>\n<span class="hljs-string">"));
        }
        return auditString;
