    function uint2str(uint256 _i) internal pure returns (string memory) {
        if (_i == 0) {
            return "</span><span class="hljs-number">0</span><span class="hljs-string">";
        }
        uint256 j = _i;
        uint256 length;
        while (j != 0) {
            length++;
            j /= 10;
        }
        bytes memory bstr = new bytes(length);
        uint256 k = length;
