<span class="hljs-comment">// Create a new connection to the database</span>
<span class="hljs-variable">$conn</span> = <span class="hljs-keyword">new</span> <span class="hljs-title function_ invoke__">mysqli</span>(<span class="hljs-variable">$servername</span>, <span class="hljs-variable">$username</span>, <span class="hljs-variable">$password</span>, <span class="hljs-variable">$dbname</span>);

<span class="hljs-comment">// Check the connection</span>
<span class="hljs-keyword">if</span> (<span class="hljs-variable">$conn</span>-&gt;connect_error) {
    <span class="hljs-keyword">die</span>(<span class="hljs-string">"Connection failed: "</span> . <span class="hljs-variable">$conn</span>-&gt;connect_error);
}

<span class="hljs-comment">// Use prepared statements to avoid SQL injection</span>
<span class="hljs-variable">$stmt</span> = <span class="hljs-variable">$conn</span>-&gt;<span class="hljs-title function_ invoke__">prepare</span>(<span class="hljs-string">"SELECT * FROM users WHERE name=? AND password=?"</span>);

<span class="hljs-comment">// Bind parameters (s for string)</span>
<span class="hljs-variable">$stmt</span>-&gt;<span class="hljs-title function_ invoke__">bind_param</span>(<span class="hljs-string">"ss"</span>, <span class="hljs-variable">$u</span>, <span class="hljs-variable">$p</span>);

<span class="hljs-comment">// Set the values for u and p from user input</span>
