} <span class="hljs-keyword">else</span> {
    <span class="hljs-keyword">echo</span> <span class="hljs-string">"No user found"</span>;
}

<span class="hljs-comment">// Close the prepared statement and the connection</span>
<span class="hljs-variable">$stmt</span>-&gt;<span class="hljs-title function_ invoke__">close</span>();
