    FILE *file = fopen(filename, <span class="hljs-string">"r"</span>);
    <span class="hljs-type">char</span> *buffer;
    <span class="hljs-type">int</span> length;

    <span class="hljs-keyword">if</span> (file == <span class="hljs-literal">NULL</span>) {
        <span class="hljs-built_in">fprintf</span>(<span class="hljs-built_in">stderr</span>, <span class="hljs-string">"Error opening file\n"</span>);
        <span class="hljs-keyword">return</span> <span class="hljs-number">1</span>;
    }

    fseek(file, <span class="hljs-number">0</span>, SEEK_END);
    length = ftell(file);
    fseek(file, <span class="hljs-number">0</span>, SEEK_SET);

    buffer = (<span class="hljs-type">char</span>*) <span class="hljs-built_in">malloc</span>(length);

    <span class="hljs-keyword">if</span> (buffer == <span class="hljs-literal">NULL</span>) {
        <span class="hljs-built_in">fprintf</span>(<span class="hljs-built_in">stderr</span>, <span class="hljs-string">"Error allocating memory\n"</span>);
        <span class="hljs-keyword">return</span> <span class="hljs-number">1</span>;
    }

    <span class="hljs-type">int</span> bytesRead = <span class="hljs-number">0</span>;
    <span class="hljs-type">int</span> bytesToRead = length;

    <span class="hljs-keyword">while</span> (bytesRead &lt; length) {
        <span class="hljs-type">int</span> bytesThisChunk = bytesToRead &gt; CHUNK_SIZE ? CHUNK_SIZE : bytesToRead;
        fread(buffer + bytesRead, bytesThisChunk, <span class="hljs-number">1</span>, file);
        bytesRead += bytesThisChunk;
        bytesToRead -= bytesThisChunk;
    }

