Future&lt;<span class="hljs-type">String</span>?&gt; <span class="hljs-title function_ invoke__">getRefreshToken</span>() <span class="hljs-keyword">async</span> {
  <span class="hljs-keyword">return</span> <span class="hljs-keyword">await</span> storage.<span class="hljs-title function_ invoke__">read</span>(key: <span class="hljs-symbol">'refresh_token</span>');
