<span class="hljs-comment">// Update the secure storage with new tokens</span>
Future&lt;void&gt; <span class="hljs-title function_ invoke__">updateTokens</span>(<span class="hljs-type">String</span> accessToken, <span class="hljs-type">String</span> refreshToken) <span class="hljs-keyword">async</span> {
  <span class="hljs-keyword">await</span> storage.<span class="hljs-title function_ invoke__">write</span>(key: <span class="hljs-symbol">'access_token</span>', value: accessToken);
  <span class="hljs-keyword">await</span> storage.<span class="hljs-title function_ invoke__">write</span>(key: <span class="hljs-symbol">'refresh_token</span>', value: refreshToken);
}

<span class="hljs-comment">// Set up an HTTP interceptor to add the tokens as headers to outgoing requests</span>
<span class="hljs-keyword">final</span> dio = <span class="hljs-title function_ invoke__">Dio</span>();
dio.interceptors.<span class="hljs-title function_ invoke__">add</span>(<span class="hljs-title function_ invoke__">InterceptorsWrapper</span>(
  onRequest: (options, handler) <span class="hljs-keyword">async</span> {
    <span class="hljs-keyword">final</span> accessToken = <span class="hljs-keyword">await</span> <span class="hljs-title function_ invoke__">getAccessToken</span>();
    <span class="hljs-title function_ invoke__">if</span> (accessToken != null) {
      options.headers[<span class="hljs-symbol">'Authorization</span>'] = <span class="hljs-symbol">'Bearer</span> $accessToken';
    }
    <span class="hljs-keyword">final</span> refreshToken = <span class="hljs-keyword">await</span> <span class="hljs-title function_ invoke__">getRefreshToken</span>();
