        <span class="hljs-variable">$pattern2</span> = { <span class="hljs-number">48</span> 8D <span class="hljs-number">05</span> <span class="hljs-string">??</span> <span class="hljs-string">??</span> <span class="hljs-string">??</span> <span class="hljs-string">??</span> <span class="hljs-number">48</span> <span class="hljs-number">89</span> 7C <span class="hljs-number">24</span> <span class="hljs-string">??</span> <span class="hljs-variable constant_">E8</span> }
        <span class="hljs-variable">$pattern3</span> = <span class="hljs-regexp">/Invoke-Expression|\$ExecutionContext|Add-Type|\$MyInvocation|Register-TypeNameForDeserialization/</span>

