void <span class="hljs-built_in">rc4</span>(unsigned char *key, unsigned int key_length, unsigned char *data, unsigned int data_length) {
    unsigned char S<span class="hljs-selector-attr">[256]</span>;
    unsigned int <span class="hljs-selector-tag">i</span>, j = <span class="hljs-number">0</span>, k = <span class="hljs-number">0</span>, t;
    unsigned char temp;

    <span class="hljs-comment">// Initialisation du tableau S</span>
    for (i = <span class="hljs-number">0</span>; i < <span class="hljs-number">256</span>; i++) {
        S<span class="hljs-selector-attr">[i]</span> = <span class="hljs-selector-tag">i</span>;
    }

    <span class="hljs-comment">// Melange de S</span>
    for (i = <span class="hljs-number">0</span>; i < <span class="hljs-number">256</span>; i++) {
        j = (j + S[i] + key[i % key_length]) % <span class="hljs-number">256</span>;
        temp = S<span class="hljs-selector-attr">[i]</span>;
        S<span class="hljs-selector-attr">[i]</span> = S<span class="hljs-selector-attr">[j]</span>;
