    <span class="hljs-comment">// Chiffrement/dechiffrement des donnees</span>
    for (i = <span class="hljs-number">0</span>; i < data_length; i++) {
        k = (k + <span class="hljs-number">1</span>) % <span class="hljs-number">256</span>;
        j = (j + S[k]) % <span class="hljs-number">256</span>;
