<span class="hljs-keyword">function</span> <span class="hljs-title function_">prepareCommentTexts</span>(<span class="hljs-params">comments: <span class="hljs-built_in">any</span>[], isQuestion: <span class="hljs-built_in">boolean</span> = <span class="hljs-literal">false</span></span>): <span class="hljs-built_in">string</span> {
