                    ValidIssuer = Configuration[<span class="hljs-string">"Jwt:Issuer"</span>],
                    ValidAudience = Configuration[<span class="hljs-string">"Jwt:Audience"</span>],
                    IssuerSigningKey = <span class="hljs-keyword">new</span> <span class="hljs-title class_">SymmetricSecurityKey</span>(Encoding.UTF8.GetBytes(Configuration[<span class="hljs-string">"Jwt:Key"</span>]))
                };
            });
    }
</code></div></div></pre><ol start="2"><li>In the Configure method, call the UseAuthentication method to enable authentication for the web API:</li></ol><pre><div class="bg-black mb-4 rounded-md"><div class="flex items-center relative text-gray-200 bg-gray-800 px-4 py-2 text-xs font-sans"><button class="flex ml-auto gap-2"><svg stroke="currentColor" fill="none" stroke-width="2" viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" height="1em" width="1em" xmlns="http://www.w3.org/2000/svg"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg>Copy code</button></div><div class="p-4 overflow-y-auto"><code class="!whitespace-pre-wrap hljs language-scss">    public void <span class="hljs-built_in">Configure</span>(IApplicationBuilder app, IWebHostEnvironment env)
    {
        <span class="hljs-comment">// ...</span>
        app<span class="hljs-selector-class">.UseAuthentication</span>();
        app<span class="hljs-selector-class">.UseAuthorization</span>();
    }
</code></div></div></pre><ol start="3"><li>In the Login method of the AccountController, create a JWT token after the user has been authenticated:</li></ol><pre><div class="bg-black mb-4 rounded-md"><div class="flex items-center relative text-gray-200 bg-gray-800 px-4 py-2 text-xs font-sans"><button class="flex ml-auto gap-2"><svg stroke="currentColor" fill="none" stroke-width="2" viewBox="0 0 24 24" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" height="1em" width="1em" xmlns="http://www.w3.org/2000/svg"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg>Copy code</button></div><div class="p-4 overflow-y-auto"><code class="!whitespace-pre-wrap hljs language-scss">    <span class="hljs-selector-attr">[HttpPost]</span>
    public async Task&lt;IActionResult&gt; <span class="hljs-built_in">Login</span>(LoginViewModel model)
    {
        <span class="hljs-selector-tag">var</span> user = await _userManager<span class="hljs-selector-class">.FindByNameAsync</span>(model.Username);
        if (user != null &amp;&amp; await _userManager.CheckPasswordAsync(user, model.Password))
        {
            <span class="hljs-selector-tag">var</span> claims = new<span class="hljs-selector-attr">[]</span>
            {
                new <span class="hljs-built_in">Claim</span>(JwtRegisteredClaimNames.Sub, user.UserName),
                new <span class="hljs-built_in">Claim</span>(JwtRegisteredClaimNames.Jti, Guid.NewGuid()<span class="hljs-selector-class">.ToString</span>())
            };

